import { Check, ChevronRight } from 'lucide-react';
import { useId, useRef, type HTMLAttributes, type KeyboardEvent, type MouseEvent, type Ref } from 'react';
import { cn } from '../../utils/cn';
import { Spinner } from '../spinner';
import { childrenOf, type TreeNode, type VisibleNode } from './tree-model';
import { treeListVariants } from './tree-list.variants';
import { useTreeList, type UseTreeListOptions } from './useTreeList';

export interface TreeListLabels {
  loading: string;
  error: string;
  retry: string;
}

const DEFAULT_LABELS: TreeListLabels = { loading: 'Loading…', error: 'Could not load items.', retry: 'Retry' };

export interface TreeListProps extends UseTreeListOptions, Omit<HTMLAttributes<HTMLUListElement>, 'className' | 'children' | 'onSelect'> {
  className?: string;
  ref?: Ref<HTMLUListElement>;
  /** Called on Enter or double click of a node (e.g. open a file). */
  onAction?: (node: TreeNode) => void;
  /** Indent per level in px. */
  indent?: number;
  /** Built-in strings (English defaults). */
  labels?: Partial<TreeListLabels>;
}

const s = treeListVariants();

/**
 * Hierarchical list on the WAI-ARIA tree pattern: roving focus, arrow keys (Left/Right
 * collapse/expand), Home/End, typeahead, single or multiple selection and lazily loaded
 * children with a loading state. Label it with `aria-label` or `aria-labelledby`.
 */
export function TreeList({
  nodes,
  expanded,
  defaultExpanded,
  onExpandedChange,
  selectionMode,
  selected,
  defaultSelected,
  onSelectedChange,
  loadChildren,
  onAction,
  indent = 16,
  labels: labelsProp,
  className,
  onKeyDown,
  ...props
}: TreeListProps) {
  const labels = { ...DEFAULT_LABELS, ...labelsProp };
  const tree = useTreeList({ nodes, expanded, defaultExpanded, onExpandedChange, selectionMode, selected, defaultSelected, onSelectedChange, loadChildren });
  const items = useRef(new Map<string, HTMLLIElement>());
  const typeahead = useRef({ text: '', at: 0 });
  const baseId = useId();
  const byId = new Map(tree.visible.map((v, i) => [v.node.id, { ...v, rowId: `${baseId}-${i}` }]));
  const multi = tree.selectionMode === 'multiple';

  const focus = (id: string | undefined) => {
    if (id === undefined) return;
    tree.setActiveId(id);
    items.current.get(id)?.focus();
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLUListElement>) => {
    onKeyDown?.(event);
    const id = (event.target as HTMLElement).closest<HTMLElement>('[role="treeitem"]')?.dataset.id;
    const index = tree.visible.findIndex((v) => v.node.id === id);
    const current = tree.visible[index];
    if (event.defaultPrevented || !current) return;
    const { node } = current;
    const rtl = getComputedStyle(event.currentTarget).direction === 'rtl';
    const key = rtl && event.key === 'ArrowLeft' ? 'ArrowRight' : rtl && event.key === 'ArrowRight' ? 'ArrowLeft' : event.key;
    const move = (target: VisibleNode | undefined) => {
      event.preventDefault();
      focus(target?.node.id);
    };

    switch (key) {
      case 'ArrowDown':
        return move(tree.visible[index + 1]);
      case 'ArrowUp':
        return move(tree.visible[index - 1]);
      case 'Home':
        return move(tree.visible[0]);
      case 'End':
        return move(tree.visible.at(-1));
      case 'ArrowRight': {
        event.preventDefault();
        if (!current.branch || node.disabled) return;
        if (!current.expanded) return tree.setOpen(node, true);
        if (tree.loaded[node.id]?.status === 'error') return tree.retry(node);
        const first = tree.visible[index + 1];
        if (first?.parentId === node.id) focus(first.node.id);
        return;
      }
      case 'ArrowLeft':
        event.preventDefault();
        if (current.expanded) return tree.setOpen(node, false);
        return focus(current.parentId);
      case 'Enter':
        event.preventDefault();
        tree.select(node, multi ? 'toggle' : 'replace');
        if (onAction && !node.disabled) onAction(node);
        else if (tree.selectionMode === 'none') tree.setOpen(node, !current.expanded);
        return;
      case ' ':
        event.preventDefault();
        if (tree.selectionMode === 'none') return tree.setOpen(node, !current.expanded);
        return tree.select(node, multi ? 'toggle' : 'replace');
    }
    if (multi && key.toLowerCase() === 'a' && (event.ctrlKey || event.metaKey)) {
      event.preventDefault();
      return tree.selectAll();
    }
    if (key.length === 1 && /\S/.test(key) && !event.ctrlKey && !event.metaKey && !event.altKey) {
      event.preventDefault();
      const t = typeahead.current;
      t.text = event.timeStamp - t.at > 500 ? key.toLowerCase() : t.text + key.toLowerCase();
      t.at = event.timeStamp;
      // Repeating one character cycles through matches; longer text refines from the current node.
      const repeat = [...t.text].every((c) => c === t.text[0]);
      const query = repeat ? t.text.charAt(0) : t.text;
      const start = index + (repeat ? 1 : 0);
      const order = [...tree.visible.slice(start), ...tree.visible.slice(0, start)];
      focus(order.find((v) => !v.node.disabled && v.node.label.toLowerCase().startsWith(query))?.node.id);
    }
  };

  const handleClick = (event: MouseEvent, v: VisibleNode) => {
    event.stopPropagation();
    if (v.node.disabled) return;
    focus(v.node.id);
    const onChevron = (event.target as HTMLElement).closest('[data-chevron]');
    if (onChevron || tree.selectionMode === 'none') return tree.setOpen(v.node, !v.expanded);
    tree.select(v.node, multi ? 'toggle' : 'replace');
  };

  const renderLevel = (list: TreeNode[]) =>
    list.map((node) => {
      const v = byId.get(node.id);
      if (!v) return null;
      const isSelected = tree.selected.has(node.id);
      const childState = tree.loaded[node.id];
      const kids = v.expanded ? childrenOf(node, tree.loaded) : undefined;
      const v2 = treeListVariants({ selected: isSelected, expanded: v.expanded, disabled: node.disabled });
      const Icon = (v.expanded && node.openIcon) || node.icon;
      const pad = { paddingInlineStart: `${(v.level - 1) * indent + 6}px` };
      return (
        <li
          key={node.id}
          ref={(el) => {
            if (el) items.current.set(node.id, el);
            else items.current.delete(node.id);
          }}
          role="treeitem"
          aria-labelledby={v.rowId}
          data-id={node.id}
          aria-level={v.level}
          aria-posinset={v.posinset}
          aria-setsize={v.setsize}
          aria-expanded={v.branch ? v.expanded : undefined}
          aria-selected={tree.selectionMode === 'none' ? undefined : isSelected}
          aria-disabled={node.disabled || undefined}
          aria-busy={childState?.status === 'loading' || undefined}
          tabIndex={node.id === tree.focusId ? 0 : -1}
          onFocus={(e) => {
            if (e.target === e.currentTarget) tree.setActiveId(node.id);
          }}
          className={s.item()}
        >
          <div data-row id={v.rowId} className={v2.row()} style={pad} onClick={(e) => handleClick(e, v)} onDoubleClick={() => onAction && !node.disabled && onAction(node)}>
            <span data-chevron aria-hidden className={v2.chevron()}>
              {v.branch && <ChevronRight size={14} />}
            </span>
            {multi && (
              <span aria-hidden className={v2.check()}>
                {isSelected && <Check size={11} strokeWidth={3} />}
              </span>
            )}
            {Icon && <Icon size={15} aria-hidden className={v2.icon()} />}
            <span className={s.label()}>{node.content ?? node.label}</span>
            {node.meta != null && <span className={s.meta()}>{node.meta}</span>}
          </div>
          {v.expanded && (kids || childState) && (
            <ul role="group" className={s.group()}>
              {kids && renderLevel(kids)}
              {!kids && childState?.status === 'loading' && (
                <li role="none" className={s.status()} style={{ paddingInlineStart: `${v.level * indent + 6}px` }}>
                  <Spinner size={13} /> {labels.loading}
                </li>
              )}
              {!kids && childState?.status === 'error' && (
                <li role="none" className={cn(s.status(), 'text-destructive-text')} style={{ paddingInlineStart: `${v.level * indent + 6}px` }}>
                  {labels.error}
                  <button
                    type="button"
                    tabIndex={-1}
                    className="underline underline-offset-2"
                    onClick={(e) => {
                      e.stopPropagation();
                      tree.retry(node);
                    }}
                  >
                    {labels.retry}
                  </button>
                </li>
              )}
            </ul>
          )}
        </li>
      );
    });

  return (
    <ul role="tree" aria-multiselectable={multi || undefined} className={cn(s.root(), className)} onKeyDown={handleKeyDown} {...props}>
      {renderLevel(nodes)}
    </ul>
  );
}

export { TreeList, type TreeListProps, type TreeListLabels } from './TreeList';
export { useTreeList, type UseTreeListOptions, type TreeSelectionMode } from './useTreeList';
export { flattenVisible, type TreeNode, type TreeIcon, type VisibleNode } from './tree-model';
export { treeListVariants, type TreeListVariantProps } from './tree-list.variants';
export { doc as treeListDoc } from './TreeList.doc';

import { tv, type VariantProps } from '../../utils/tv';

export const treeListVariants = tv({
  slots: {
    root: 'm-0 list-none p-0 text-[13px] outline-none',
    group: 'm-0 list-none p-0',
    item: [
      'outline-none',
      '[&:focus-visible>[data-row]]:outline-2 [&:focus-visible>[data-row]]:-outline-offset-2 [&:focus-visible>[data-row]]:outline-focus-ring',
    ],
    row: [
      'flex h-8 cursor-default items-center gap-1.5 rounded-md pe-2 text-foreground transition-colors select-none',
      'hover:bg-secondary/70',
    ],
    chevron: 'grid size-4 shrink-0 place-items-center text-muted-foreground transition-transform duration-150 motion-reduce:transition-none rtl:-scale-x-100',
    icon: 'shrink-0 text-muted-foreground',
    label: 'min-w-0 flex-1 truncate text-start',
    meta: 'shrink-0 font-mono text-[11px] text-muted-foreground',
    check: 'grid size-4 shrink-0 place-items-center rounded-[4px] border border-border text-primary-foreground',
    status: 'flex h-8 items-center gap-2 pe-2 text-[12px] text-muted-foreground',
  },
  variants: {
    selected: {
      true: { row: 'bg-primary/14 text-primary-chip-text hover:bg-primary/18', icon: 'text-primary-chip-text', check: 'border-primary bg-primary' },
    },
    expanded: { true: { chevron: 'rotate-90 rtl:-rotate-90' } },
    disabled: { true: { row: 'pointer-events-none opacity-50' } },
  },
});

export type TreeListVariantProps = VariantProps<typeof treeListVariants>;

import type { ComponentType, ReactNode } from 'react';

export type TreeIcon = ComponentType<{ size?: number; 'aria-hidden'?: boolean; className?: string }>;

export interface TreeNode {
  id: string;
  /** Plain-text label; also used by typeahead. */
  label: string;
  /** Rich row content shown instead of `label` (which stays the typeahead text). */
  content?: ReactNode;
  /** Secondary text at the inline end (count, size, status). */
  meta?: ReactNode;
  /** Leading icon. */
  icon?: TreeIcon;
  /** Icon while expanded (e.g. FolderOpen). */
  openIcon?: TreeIcon;
  children?: TreeNode[];
  /** Has children that `loadChildren` fetches on first expand. */
  hasChildren?: boolean;
  disabled?: boolean;
}

export type ChildState = { status: 'loading' } | { status: 'error' } | { status: 'loaded'; nodes: TreeNode[] };

export interface VisibleNode {
  node: TreeNode;
  level: number;
  parentId: string | undefined;
  posinset: number;
  setsize: number;
  /** Has (or may lazily have) children. */
  branch: boolean;
  expanded: boolean;
}

export function childrenOf(node: TreeNode, loaded: Record<string, ChildState>) {
  if (node.children) return node.children;
  const state = loaded[node.id];
  return state?.status === 'loaded' ? state.nodes : undefined;
}

export function isBranch(node: TreeNode) {
  return (node.children?.length ?? 0) > 0 || node.hasChildren === true;
}

/** Depth-first list of the nodes a user can currently see (ancestors expanded). */
export function flattenVisible(nodes: TreeNode[], expanded: ReadonlySet<string>, loaded: Record<string, ChildState>) {
  const out: VisibleNode[] = [];
  const walk = (list: TreeNode[], level: number, parentId: string | undefined) => {
    list.forEach((node, i) => {
      const branch = isBranch(node);
      const open = branch && expanded.has(node.id);
      out.push({ node, level, parentId, posinset: i + 1, setsize: list.length, branch, expanded: open });
      const kids = open ? childrenOf(node, loaded) : undefined;
      if (kids) walk(kids, level + 1, node.id);
    });
  };
  walk(nodes, 1, undefined);
  return out;
}

/** Every enabled node id in the tree (loaded children included). */
export function allIds(nodes: TreeNode[], loaded: Record<string, ChildState>): string[] {
  return nodes.flatMap((n) => [...(n.disabled ? [] : [n.id]), ...allIds(childrenOf(n, loaded) ?? [], loaded)]);
}

import { useMemo, useRef, useState } from 'react';
import { allIds, flattenVisible, isBranch, type ChildState, type TreeNode } from './tree-model';

export type TreeSelectionMode = 'none' | 'single' | 'multiple';

export interface UseTreeListOptions {
  nodes: TreeNode[];
  expanded?: string[];
  defaultExpanded?: string[];
  onExpandedChange?: (ids: string[]) => void;
  selectionMode?: TreeSelectionMode;
  selected?: string[];
  defaultSelected?: string[];
  onSelectedChange?: (ids: string[]) => void;
  loadChildren?: (node: TreeNode) => Promise<TreeNode[]>;
}

/** State, async loading and selection for TreeList (controlled or uncontrolled). */
export function useTreeList({
  nodes,
  expanded: expandedProp,
  defaultExpanded = [],
  onExpandedChange,
  selectionMode = 'single',
  selected: selectedProp,
  defaultSelected = [],
  onSelectedChange,
  loadChildren,
}: UseTreeListOptions) {
  const [expandedState, setExpandedState] = useState(defaultExpanded);
  const [selectedState, setSelectedState] = useState(defaultSelected);
  const [loaded, setLoaded] = useState<Record<string, ChildState>>({});
  const [activeId, setActiveId] = useState<string | undefined>(undefined);
  const pending = useRef(new Set<string>());

  const expandedIds = expandedProp ?? expandedState;
  const selectedIds = selectedProp ?? selectedState;
  const expanded = useMemo(() => new Set(expandedIds), [expandedIds]);
  const selected = useMemo(() => new Set(selectedIds), [selectedIds]);
  const visible = useMemo(() => flattenVisible(nodes, expanded, loaded), [nodes, expanded, loaded]);

  const setExpanded = (ids: string[]) => {
    if (expandedProp === undefined) setExpandedState(ids);
    onExpandedChange?.(ids);
  };
  const setSelected = (ids: string[]) => {
    if (selectedProp === undefined) setSelectedState(ids);
    onSelectedChange?.(ids);
  };

  const load = (node: TreeNode) => {
    if (!loadChildren || node.children || pending.current.has(node.id) || loaded[node.id]?.status === 'loaded') return;
    pending.current.add(node.id);
    setLoaded((m) => ({ ...m, [node.id]: { status: 'loading' } }));
    loadChildren(node).then(
      (kids) => setLoaded((m) => ({ ...m, [node.id]: { status: 'loaded', nodes: kids } })),
      () => setLoaded((m) => ({ ...m, [node.id]: { status: 'error' } })),
    ).finally(() => pending.current.delete(node.id));
  };

  const setOpen = (node: TreeNode, open: boolean) => {
    if (!isBranch(node) || expanded.has(node.id) === open) return;
    if (open) load(node);
    setExpanded(open ? [...expandedIds, node.id] : expandedIds.filter((id) => id !== node.id));
  };

  const select = (node: TreeNode, mode: 'replace' | 'toggle' = 'replace') => {
    if (selectionMode === 'none' || node.disabled) return;
    if (selectionMode === 'single') return setSelected([node.id]);
    if (mode === 'toggle') setSelected(selected.has(node.id) ? selectedIds.filter((id) => id !== node.id) : [...selectedIds, node.id]);
    else setSelected([node.id]);
  };

  const selectAll = () => {
    if (selectionMode === 'multiple') setSelected(allIds(nodes, loaded));
  };

  /** Re-requests children after a failed load. */
  const retry = (node: TreeNode) => load(node);

  const focusId = activeId !== undefined && visible.some((v) => v.node.id === activeId) ? activeId : (visible.find((v) => selected.has(v.node.id))?.node.id ?? visible[0]?.node.id);

  return { visible, expanded, selected, loaded, focusId, setActiveId, setOpen, select, selectAll, retry, selectionMode };
}
